import{_ as t,o,c as a,a1 as i}from"./chunks/framework.C5u0ZYB0.js";const p=JSON.parse('{"title":"Limitations & downsides","description":"","frontmatter":{},"headers":[],"relativePath":"docs/limitations.md","filePath":"docs/limitations.md","lastUpdated":1789983439000}'),r={name:"docs/limitations.md"};function s(n,e,l,d,c,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="limitations-downsides" tabindex="-1">Limitations &amp; downsides <a class="header-anchor" href="#limitations-downsides" aria-label="Permalink to &quot;Limitations &amp; downsides&quot;">​</a></h1><p>Every project has tradeoffs. This page exists so they&#39;re written down plainly instead of left for you to discover after the fact; the goal is that nothing here should surprise you.</p><h2 id="security-storage" tabindex="-1">Security &amp; storage <a class="header-anchor" href="#security-storage" aria-label="Permalink to &quot;Security &amp; storage&quot;">​</a></h2><ul><li><strong>API keys are stored as plain text by default.</strong> The <a href="/projects/aquilifer/docs/vault">vault</a> is optional, off by default. <code>chrome.storage.local</code> is sandboxed from websites (no site can ever read it), but it isn&#39;t encrypted on disk. This is an accepted tradeoff: an API key is revocable and cheap to rotate if it&#39;s ever exposed some other way, unlike, say, a cryptocurrency wallet&#39;s private key.</li><li><strong>The vault, once turned on, only encrypts API keys</strong>, not your request history, not your connected-site list. If you&#39;re typing anything sensitive into a site that uses Aquilifer, a record of it sits in local, unencrypted browser storage regardless of whether the vault is on. See <a href="/projects/aquilifer/docs/history">History</a> and <a href="/projects/aquilifer/docs/vault">The vault</a>.</li><li><strong>The vault has no password recovery.</strong> Forgetting it permanently loses access to the API keys it protected; you&#39;d re-add those providers with a fresh key. This is by design, not an oversight (see <a href="/projects/aquilifer/docs/vault">The vault</a> for why).</li><li><strong>Rate limits protect against accidents, not a determined attacker.</strong> They&#39;re self-configured and self-imposed: a real safeguard against a bug or an unexpectedly chatty integration running up your bill, not a security boundary enforceable against a hostile site that&#39;s determined to work around it.</li></ul><h2 id="what-aquilifer-doesn-t-do" tabindex="-1">What Aquilifer doesn&#39;t do <a class="header-anchor" href="#what-aquilifer-doesn-t-do" aria-label="Permalink to &quot;What Aquilifer doesn&#39;t do&quot;">​</a></h2><ul><li><strong>Requires a pay-per-token API key, not a consumer subscription.</strong> Every <a href="/projects/aquilifer/docs/providers">provider</a> Aquilifer connects to is authenticated with that provider&#39;s own API key, billed per token used. A Claude Pro/Max subscription, a ChatGPT Plus subscription, or a GitHub Copilot subscription is a different product with a different authentication model (a logged-in session, not an API key) and can&#39;t be used here; connecting a provider means generating a key from that provider&#39;s own developer console, with its own separate, usage-based billing on top of (not instead of) any consumer subscription you already pay for.</li><li><strong>A site can never use two providers at once.</strong> Exactly one provider is bound per site at a time; a provider-specific interface needing a different type triggers a switch (replacing the binding), never a second grant.</li><li><strong>The generic chat interface is text-in, text-out only</strong>: no tool use, images, or structured output. A site needing those has to use the <a href="/projects/aquilifer/docs/anthropic-api">Anthropic Claude</a> or <a href="/projects/aquilifer/docs/openai-compatible-api">OpenAI-compatible</a> interface instead, and accept being tied to that provider&#39;s native request shape.</li><li><strong>No password/settings sync across devices.</strong> Everything Aquilifer stores is local to one browser profile on one machine; connecting a provider on your laptop doesn&#39;t carry over to your desktop.</li></ul><h2 id="platform-maturity" tabindex="-1">Platform &amp; maturity <a class="header-anchor" href="#platform-maturity" aria-label="Permalink to &quot;Platform &amp; maturity&quot;">​</a></h2><ul><li><strong>Chrome (and other Chromium browsers) only, for now.</strong> Aquilifer targets Manifest V3; Firefox, Safari, and other browsers aren&#39;t supported yet.</li><li><strong>Not on the Chrome Web Store yet</strong>: install from source (see <a href="/projects/aquilifer/docs/installing">Installing</a>). Updates aren&#39;t automatic until it&#39;s published there.</li></ul><h2 id="found-something-not-listed-here" tabindex="-1">Found something not listed here? <a class="header-anchor" href="#found-something-not-listed-here" aria-label="Permalink to &quot;Found something not listed here?&quot;">​</a></h2><p>This page is meant to grow, not shrink. If you run into a limitation that isn&#39;t written down here, <a href="https://github.com/On0n0k1/aquilifer/issues" target="_blank" rel="noreferrer">open an issue</a>.</p>',10)])])}const f=t(r,[["render",s]]);export{p as __pageData,f as default};
